using System.Text;

namespace CityBuilder.DocTools;

/// <summary>
/// Builds one generated page as plain CommonMark with GitHub tables and Mermaid blocks, the only Markdown the handbook takes
/// (core-instructions/17-documentation-system.md §7). The text is the same on every machine: <c>\n</c> line ends, no timestamps, no
/// absolute paths; the callers sort what they list.
/// </summary>
public sealed class MarkdownPage
{
    /// <summary>The first line of every generated page (core-instructions/17-documentation-system.md §3).</summary>
    public const string Notice =
        "Generated by tools/DocTools — do not edit. Regenerate with `dotnet run --project tools/DocTools -- generate` (docs/modules/DocTools.md).";

    /// <summary>The page's text so far.</summary>
    private readonly StringBuilder _text = new();

    /// <summary>Starts a page with the notice, its title and the line that says where its facts come from.</summary>
    /// <param name="title">The page's title, the only level-1 heading.</param>
    /// <param name="sources">Where the facts come from, as Markdown (paths in backticks).</param>
    public MarkdownPage(string title, string sources)
    {
        Line(Notice).Line().Line("# " + title).Line().Line("Source: " + sources + ". The normative specs stay in `core-instructions/`; this page shows the code as built.").Line();
    }

    /// <summary>Adds a heading and a blank line after it.</summary>
    /// <param name="level">2 to 4; the title is the only level 1.</param>
    /// <param name="text">The heading text (plain, escaped like a table cell).</param>
    /// <returns>This page.</returns>
    public MarkdownPage Heading(int level, string text) => Line(new string('#', level) + " " + Text(text)).Line();

    /// <summary>Adds a paragraph and a blank line after it.</summary>
    /// <param name="markdown">The paragraph as Markdown; the caller escapes what needs it.</param>
    /// <returns>This page.</returns>
    public MarkdownPage Paragraph(string markdown) => Line(markdown).Line();

    /// <summary>Adds a GitHub table and a blank line after it. A table without rows becomes the line "None." instead.</summary>
    /// <param name="headers">The column headers (plain text).</param>
    /// <param name="rows">The rows, each with one cell per header, already formatted with <see cref="Text"/> or <see cref="Code"/>.</param>
    /// <returns>This page.</returns>
    /// <exception cref="ArgumentException">A row's cell count differs from the headers'.</exception>
    public MarkdownPage Table(IReadOnlyList<string> headers, IEnumerable<IReadOnlyList<string>> rows)
    {
        ArgumentNullException.ThrowIfNull(headers);
        ArgumentNullException.ThrowIfNull(rows);
        List<IReadOnlyList<string>> all = [.. rows];
        if (all.Count == 0)
        {
            return Paragraph("None.");
        }

        Line("| " + string.Join(" | ", headers.Select(Text)) + " |");
        Line("|" + string.Concat(headers.Select(_ => "---|")));
        foreach (IReadOnlyList<string> row in all)
        {
            if (row.Count != headers.Count)
            {
                throw new ArgumentException($"A row has {row.Count} cells for {headers.Count} headers.", nameof(rows));
            }

            Line("| " + string.Join(" | ", row) + " |");
        }

        return Line();
    }

    /// <summary>Adds a fenced Mermaid diagram and a blank line after it.</summary>
    /// <param name="lines">The diagram's lines, without the fence.</param>
    /// <returns>This page.</returns>
    public MarkdownPage Mermaid(IEnumerable<string> lines)
    {
        ArgumentNullException.ThrowIfNull(lines);
        Line("```mermaid");
        foreach (string line in lines)
        {
            Line(line);
        }

        return Line("```").Line();
    }

    /// <summary>The finished page.</summary>
    /// <param name="fileName">Its file name in <c>docs/reference/generated/</c>.</param>
    /// <returns>The page, ending in exactly one line end.</returns>
    public GeneratedPage ToPage(string fileName) => new(fileName, _text.ToString().TrimEnd('\n') + "\n");

    /// <summary>
    /// Plain text made safe for a table cell, a heading or a sentence: a pipe would end the cell, an angle bracket would read as HTML on the
    /// handbook (17 §7), and a line end would end the row.
    /// </summary>
    /// <param name="text">The text, as it is in the code or the content.</param>
    /// <returns>The escaped text; an empty cell for null or empty text.</returns>
    public static string Text(string? text) =>
        string.IsNullOrEmpty(text)
            ? string.Empty
            : text.Replace("\r\n", " ", StringComparison.Ordinal).Replace('\n', ' ').Replace("|", "\\|", StringComparison.Ordinal)
                .Replace("<", "&lt;", StringComparison.Ordinal).Replace(">", "&gt;", StringComparison.Ordinal);

    /// <summary>Text as inline code, for ids, keys, paths and types. Inside a table only the pipe needs escaping.</summary>
    /// <param name="text">The code text.</param>
    /// <returns>The text in backticks; an empty cell for null or empty text.</returns>
    public static string Code(string? text) =>
        string.IsNullOrEmpty(text) ? string.Empty : "`" + text.Replace("|", "\\|", StringComparison.Ordinal) + "`";

    /// <summary>Appends one line (an empty one by default) and its line end.</summary>
    /// <param name="line">The line's text.</param>
    /// <returns>This page.</returns>
    private MarkdownPage Line(string line = "")
    {
        _text.Append(line).Append('\n');
        return this;
    }
}
